{
  "title": "Tính góc nhị diện giữa mặt phẳng (SBC) và mặt phẳng đáy (ABCD)",
  "description": "Tính góc nhị diện tạo bởi mặt phẳng (SBC) và mặt phẳng đáy (ABCD) dọc theo cạnh chung BC của hình chóp S.ABCD có đáy ABCD là hình vuông cạnh a, cạnh bên SA vuông góc với mặt phẳng đáy và SA = a.",
  "memory_declarations": [
    {
      "name": "a",
      "type": "float",
      "initial_value": 1.0,
      "model_assumption": "Chọn a = 1 để đơn giản hóa tọa độ và tính toán."
    },
    {
      "name": "A",
      "type": "point3",
      "at": [0, 0, 0],
      "label": "Điểm A"
    },
    {
      "name": "B",
      "type": "point3",
      "at": [
        { "kind": "var", "name": "a" },
        0,
        0
      ],
      "label": "Điểm B"
    },
    {
      "name": "C",
      "type": "point3",
      "at": [
        { "kind": "var", "name": "a" },
        { "kind": "var", "name": "a" },
        0
      ],
      "label": "Điểm C"
    },
    {
      "name": "D",
      "type": "point3",
      "at": [
        0,
        { "kind": "var", "name": "a" },
        0
      ],
      "label": "Điểm D"
    },
    {
      "name": "S",
      "type": "point3",
      "at": [
        0,
        0,
        { "kind": "var", "name": "a" }
      ],
      "label": "Điểm S"
    },
    {
      "name": "plane_ABCD",
      "type": "plane3",
      "label": "Mặt phẳng đáy (ABCD)"
    },
    {
      "name": "plane_SBC",
      "type": "plane3",
      "label": "Mặt phẳng (SBC)"
    },
    {
      "name": "line_BC",
      "type": "line3",
      "label": "Cạnh chung BC"
    },
    {
      "name": "line_AB",
      "type": "line3",
      "label": "Đường thẳng AB"
    },
    {
      "name": "line_SB",
      "type": "line3",
      "label": "Đường thẳng SB"
    },
    {
      "name": "dihedral_angle",
      "type": "float",
      "label": "Góc nhị diện"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "label": "Đặt A tại gốc tọa độ"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [
        { "kind": "var", "name": "a" },
        0,
        0
      ],
      "label": "Xác định B trên trục Ox"
    },
    {
      "kind": "declare_point",
      "target_var": "D",
      "at": [
        0,
        { "kind": "var", "name": "a" },
        0
      ],
      "label": "Xác định D trên trục Oy"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [
        { "kind": "var", "name": "a" },
        { "kind": "var", "name": "a" },
        0
      ],
      "label": "Xác định C để hoàn thành hình vuông ABCD"
    },
    {
      "kind": "declare_point",
      "target_var": "S",
      "at": [
        0,
        0,
        { "kind": "var", "name": "a" }
      ],
      "label": "Xác định S trên trục Oz (SA vuông góc đáy và SA=a)"
    },
    {
      "kind": "construct_plane",
      "target_var": "plane_ABCD",
      "through": ["A", "B", "C"],
      "label": "Dựng mặt phẳng đáy (ABCD)"
    },
    {
      "kind": "construct_plane",
      "target_var": "plane_SBC",
      "through": ["S", "B", "C"],
      "label": "Dựng mặt phẳng (SBC)"
    },
    {
      "kind": "construct_line",
      "target_var": "line_BC",
      "through_a": "B",
      "through_b": "C",
      "label": "Xác định giao tuyến BC"
    },
    {
      "kind": "construct_line",
      "target_var": "line_AB",
      "through_a": "A",
      "through_b": "B",
      "label": "Dựng AB trong (ABCD) vuông góc với BC"
    },
    {
      "kind": "construct_line",
      "target_var": "line_SB",
      "through_a": "S",
      "through_b": "B",
      "label": "Dựng SB trong (SBC) vuông góc với BC"
    },
    {
      "kind": "assign",
      "target_var": "dihedral_angle",
      "expr": {
        "kind": "measure",
        "quantity": "angle",
        "of": "line_AB",
        "wrt": "line_SB"
      }
    }
  ],
  "visual_bindings": {
    "containers": [],
    "pointers": [],
    "value_boxes": [
      {
        "box_id": "box_a",
        "var_ref": "a",
        "label": "Độ dài cạnh a"
      },
      {
        "box_id": "box_dihedral_angle",
        "var_ref": "dihedral_angle",
        "label": "Góc nhị diện (độ)"
      }
    ]
  },
  "pedagogical_intent": "Mô phỏng các bước xác định góc nhị diện giữa hai mặt phẳng bằng cách tìm hai đường thẳng cùng vuông góc với giao tuyến tại một điểm, mỗi đường thuộc một mặt phẳng."
}

